function ViewportTooltipLayer(){
 const [owner,setOwner]=useState<HTMLElement|null>(null),[rect,setRect]=useState<{left:number;top:number}|null>(null),tip=useRef<HTMLDivElement>(null);
 useEffect(()=>{let hovered:HTMLElement|null=null;const eligible=(node:EventTarget|null)=>{const element=node instanceof Element?node.closest<HTMLElement>('[data-tooltip]'):null;return element&&element.closest('.guided-character-editor,.model-workbench-document')?element:null};const over=(event:Event)=>{const next=eligible(event.target);if(next){hovered=next;setOwner(next)}};const out=(event:Event)=>{if(hovered&&event instanceof PointerEvent&&event.relatedTarget instanceof Node&&hovered.contains(event.relatedTarget))return;if(hovered&&document.activeElement===hovered)return;hovered=null;setOwner(null)};const focus=(event:Event)=>{const next=eligible(event.target);if(next){hovered=next;setOwner(next)}else if(hovered&&document.activeElement!==hovered){hovered=null;setOwner(null)}};const key=(event:KeyboardEvent)=>{if(event.key==='Escape'){hovered=null;setOwner(null)}};document.addEventListener('pointerover',over,true);document.addEventListener('pointerout',out,true);document.addEventListener('focusin',focus,true);document.addEventListener('focusout',focus,true);document.addEventListener('keydown',key,true);return()=>{document.removeEventListener('pointerover',over,true);document.removeEventListener('pointerout',out,true);document.removeEventListener('focusin',focus,true);document.removeEventListener('focusout',focus,true);document.removeEventListener('keydown',key,true)}},[]);
 useLayoutEffect(()=>{if(!owner||!tip.current){setRect(null);return}const place=()=>{if(!owner.isConnected){setOwner(null);return}const anchor=owner.getBoundingClientRect(),box=tip.current!.getBoundingClientRect(),pad=12,left=Math.max(pad,Math.min(anchor.left+anchor.width/2-box.width/2,window.innerWidth-box.width-pad)),above=anchor.top-box.height-8>=pad,top=Math.max(pad,Math.min(above?anchor.top-box.height-8:anchor.bottom+8,window.innerHeight-box.height-pad));setRect({left,top})};place();const observer=new ResizeObserver(place);observer.observe(owner);observer.observe(tip.current);window.addEventListener('resize',place);window.addEventListener('scroll',place,true);return()=>{observer.disconnect();window.removeEventListener('resize',place);window.removeEventListener('scroll',place,true)}},[owner,owner?.getAttribute('data-tooltip')]);
 if(!owner||!document.body)return null;return createPortal(<div ref={tip} className="viewport-tooltip" role="tooltip" style={{left:rect?.left??0,top:rect?.top??0,visibility:rect?'visible':'hidden'}}>{owner.getAttribute('data-tooltip')}</div>,document.body)
}
