async function droppedFilePaths(files:FileList|File[]){const paths=await Promise.all(Array.from(files).map(file=>window.atelier.pathForFile(file)));if(paths.some(value=>typeof value!=='string'||!value.trim()))throw new Error('Electron could not resolve a local path for one of the dropped files.');return paths;}
