function MorphingButton({children,onClick,disabled,className='primary-button',labels}:any){const [state,setState]=useState<'idle'|'busy'|'success'|'error'>('idle');const [message,setMessage]=useState('');const run=async()=>{if(disabled||state==='busy')return;setState('busy');setMessage('');try{const result=await onClick();if(result===false)throw new Error('The operation did not complete.');setState('success');window.setTimeout(()=>setState('idle'),1600);}catch(error){setMessage(error instanceof Error?error.message:String(error));setState('error');window.setTimeout(()=>setState('idle'),2400);}};const label=labels?.[state];return <button type="button" className={`${className} morphing-button morphing-${state}`} disabled={disabled||state==='busy'} aria-live="polite" aria-label={message||label} title={message||undefined} onClick={()=>void run()}>{state==='busy'?<span className="morph-spinner" aria-hidden="true"/>:state==='success'?<Check size={14}/>:state==='error'?<CircleAlert size={14}/>:null}{label||children}</button>}
function edgeGlow(event:React.PointerEvent<HTMLElement>){const rect=event.currentTarget.getBoundingClientRect();event.currentTarget.style.setProperty('--glow-x',`${event.clientX-rect.left}px`);event.currentTarget.style.setProperty('--glow-y',`${event.clientY-rect.top}px`);}
function GalleryPickerEntry({entry,image,checked,onOpen,previewEnabled,locale='en'}:any){const [preview,setPreview]=useState(''),row=useRef<HTMLButtonElement>(null);useEffect(()=>{let alive=true,observer:IntersectionObserver|undefined;if(image&&previewEnabled&&row.current){observer=new IntersectionObserver(entries=>{if(entries.some(item=>item.isIntersecting)){observer?.disconnect();void call({op:'file:gallery-preview',path:entry.path}).then((result:any)=>{if(alive&&result.ok)setPreview(result.data.url)})}});observer.observe(row.current)}return()=>{alive=false;observer?.disconnect()}},[entry.path,image,previewEnabled]);return <button ref={row} type="button" className={checked?'picked':''} aria-pressed={checked} onClick={onOpen}><span className={entry.directory?'folder-icon':'file-icon'}>{entry.directory?<FolderOpen size={16}/>:preview?<img className="picker-thumb" src={preview} alt=""/>:<FileImage size={16}/>}</span><span className="picker-entry-name">{entry.name}</span>{entry.directory?<ChevronRight size={14}/>:image?<span className="picker-entry-check">{checked?'✓':textFor(locale,'Select files')}</span>:<span className="muted">{textFor(locale,'Not an image')}</span>}</button>}
function SpecularButton({children,onClick,className=''}:any){const ref=useRef<HTMLButtonElement>(null),frame=useRef(0);const move=(event:React.PointerEvent<HTMLButtonElement>)=>{const node=ref.current;if(!node)return;const rect=node.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;cancelAnimationFrame(frame.current);frame.current=requestAnimationFrame(()=>{node.style.setProperty('--specular-x',`${x}px`);node.style.setProperty('--specular-y',`${y}px`);});};useEffect(()=>()=>cancelAnimationFrame(frame.current),[]);return <button ref={ref} className={`primary-button specular-button ${className}`} onClick={onClick} onPointerMove={move}>{children}</button>}
function ThemeToggle({value,onChange,locale='en'}:any){const dark=value==='dark',ru=locale==='ru';return <button type="button" role="switch" aria-checked={dark} aria-label={ru?(dark?'Тема NightSky':'Тема AetherSky'):(dark?'Тема NightSky':'Тема AetherSky')} className={`liquid-toggle ${dark?'is-dark':'is-light'}`} onClick={()=>onChange(dark?'light':'dark')}><span className="liquid-toggle-track"><i/></span><span>{ru?(dark?'NightSky':'AetherSky'):(dark?'NightSky':'AetherSky')}</span></button>}
function PageHeading({title,subtitle,action,onAction,locale='en'}:any){return <div className="page-heading"><div><h1>{textFor(locale,title)}</h1><p>{textFor(locale,subtitle)}</p></div>{action&&onAction&&<button className="primary-button" onClick={onAction}><Plus size={16}/>{textFor(locale,action)}</button>}</div>}
