 {entity.kind==='unityReport'&&<><UnityReportFields entity={entity} files={files} onRefresh={onRefresh} onNotify={onNotify} locale={locale} Select={MenuSelect} translate={textFor}/><button type="button" className="archive-record-action" onClick={()=>onArchive(entity,entity.data.archived!==true)}>{entity.data.archived?(locale==='ru'?'Восстановить отчёт':'Restore report'):(locale==='ru'?'В архив':'Archive report')}</button></>}
